<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {Search,Send,Plus,ArrowLeft,MessagesSquare,X} from 'lucide-vue-next';import {useWorkspace} from '../stores/workspace';import {useSession} from '../stores/session';import Avatar from '../components/Avatar.vue';import Channel from '../components/Channel.vue';import Notice from '../components/Notice.vue';import {date,time} from '../utils/format'
const w=useWorkspace(),s=useSession(),route=useRoute(),search=ref(''),status=ref('all'),selected=ref<number|null>(null),draft=ref(''),error=ref(''),busy=ref(false),lookup=ref(''),show=ref(false),customer=ref(''),channel=ref('whatsapp');let requestId=0
const items=computed(()=>w.conversations.filter(c=>(status.value==='all'||c.status===status.value)&&`${w.customers.find(x=>x.id===c.customer_id)?.name||''} ${c.id}`.toLowerCase().includes(search.value.toLowerCase())));const conversation=computed(()=>w.conversations.find(c=>c.id===selected.value));const person=computed(()=>w.customers.find(c=>c.id===conversation.value?.customer_id));const messages=computed(()=>w.messages.filter(m=>m.conversation_id===selected.value));
async function select(id:number){const current=++requestId;selected.value=id;error.value='';draft.value='';busy.value=true;try{await w.loadMessages(id)}catch(e){if(current===requestId)error.value=(e as Error).message}finally{if(current===requestId)busy.value=false}}
watch(()=>[route.query.id,w.conversations.length],()=>{const id=Number(route.query.id);if(id>0&&Number.isSafeInteger(id)&&selected.value===null)select(id)},{immediate:true})
async function create(){busy.value=true;error.value='';try{const c=await w.createConversation(Number(customer.value),channel.value);show.value=false;await select(c.id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function reply(){if(draft.value.trim()){w.reply(selected.value!,draft.value.trim());draft.value=''}}
</script>
<template><div class="page-heading compact"><div><div class="eyebrow">CADA MENSAJE CUENTA</div><h1>Conversaciones</h1><p>La atención empieza por escuchar.</p></div><button class="button primary" @click="show=true;error='' "><Plus :size="18"/>Nueva conversación</button></div><Notice v-if="s.mode==='demo'">Bandeja de ejemplo. Las respuestas son locales; ningún mensaje se entrega a un canal.</Notice><Notice v-else>La API no lista conversaciones. Aquí aparecen las creadas en esta sesión. Puedes consultar un historial por ID. El envío a canales está pendiente.</Notice>
<div class="inbox card" :class="{'has-selection':selected!==null}"><section class="conversation-list" aria-label="Lista de conversaciones"><div class="inbox-list-heading"><h2>Bandeja de entrada <span class="count-badge">{{items.length}}</span></h2><label class="search-field"><Search :size="16"/><input v-model="search" placeholder="Buscar conversación…" aria-label="Buscar conversación"></label><div class="tabs"><button v-for="tab in [{id:'all',label:'Todas'},{id:'open',label:'Abiertas'},{id:'closed',label:'Cerradas'}]" :key="tab.id" :class="{selected:status===tab.id}" @click="status=tab.id">{{tab.label}}</button></div></div><form v-if="s.mode==='live'" class="lookup" @submit.prevent="select(Number(lookup))"><input v-model="lookup" type="number" min="1" max="9007199254740991" step="1" required placeholder="ID de conversación" aria-label="ID de conversación"><button class="button" :disabled="busy">Consultar</button></form><div class="conversation-scroll"><button v-for="c in items" :key="c.id" class="conversation-item" :class="{selected:selected===c.id}" @click="select(c.id)"><Avatar :name="w.customers.find(x=>x.id===c.customer_id)?.name||'Cliente'" :index="c.customer_id"/><div><div class="conversation-title"><strong>{{w.customers.find(x=>x.id===c.customer_id)?.name||`Cliente #${c.customer_id}`}}</strong><small>{{time(w.messages.filter(m=>m.conversation_id===c.id).at(-1)?.created_at||c.created_at)}}</small></div><p>{{w.messages.filter(m=>m.conversation_id===c.id).at(-1)?.content||'Aún no hay mensajes'}}</p><div class="conversation-meta"><Channel :channel="c.channel"/><span class="status" :class="c.status">{{c.status==='open'?'Abierta':'Cerrada'}}</span></div></div></button><div v-if="!items.length" class="empty"><MessagesSquare/><p>No hay conversaciones para mostrar.</p></div></div></section>
<section class="message-panel" aria-label="Historial de mensajes"><template v-if="selected!==null"><div class="chat-heading"><button class="icon-button back-inbox" aria-label="Volver a la lista" @click="selected=null;requestId++;busy=false"><ArrowLeft :size="20"/></button><Avatar :name="person?.name||'Cliente'" :index="person?.id"/><div><h2>{{person?.name||`Conversación #${selected}`}}</h2><small>{{person?.external_id||'Historial consultado por ID'}}</small></div><div class="chat-heading-right"><Channel v-if="conversation" :channel="conversation.channel"/><span v-if="conversation" class="status" :class="conversation.status">{{conversation.status==='open'?'Abierta':'Cerrada'}}</span></div></div><Notice v-if="error" error>{{error}} <button @click="select(selected!)">Reintentar</button></Notice><div v-if="busy" class="loading" role="status">Cargando historial…</div><div v-else class="message-scroll" aria-live="polite"><div class="chat-date">{{messages.length?date(messages[0].created_at):'Una nueva conversación'}}</div><div v-if="!messages.length&&!error" class="empty"><MessagesSquare/><h3>Todo comienza con un mensaje</h3><p>{{s.mode==='demo'?'Prueba una respuesta de demostración.':'No hay mensajes en este historial.'}}</p></div><div v-for="m in messages" :key="m.id" class="message-row" :class="m.direction"><Avatar v-if="m.direction==='inbound'" :name="person?.name||'Cliente'" :index="person?.id"/><div class="bubble"><p>{{m.content}}</p><small>{{date(m.created_at)}} · {{time(m.created_at)}} <span v-if="m.direction==='outbound'">· {{s.mode==='demo'?'Demo':'Registrado'}}</span></small></div></div></div><form class="composer" @submit.prevent="reply"><label class="sr-only" for="reply">Escribe una respuesta</label><textarea id="reply" v-model="draft" rows="2" :disabled="s.mode!=='demo'||busy" :placeholder="s.mode==='demo'?'Escribe una respuesta de demostración…':'Envío pendiente de integración con un canal'" maxlength="10000"></textarea><div><small>{{s.mode==='demo'?'Solo demostración · No se enviará a ningún canal':'El endpoint de mensajes solo persiste datos; no entrega respuestas.'}}</small><button class="button primary" :disabled="s.mode!=='demo'||!draft.trim()||busy" type="submit"><Send :size="16"/>{{s.mode==='demo'?'Simular respuesta':'Envío pendiente'}}</button></div></form></template><div v-else class="inbox-welcome"><span class="welcome-icon"><MessagesSquare :size="32"/></span><h2>Conversaciones que conectan.</h2><p>Selecciona una conversación para ver su historial<br>y darle contexto a cada respuesta.</p><span class="chip">{{s.mode==='demo'?'Espacio demostrativo':'Datos de tu organización'}}</span></div></section></div>
<dialog v-modal v-if="show" open class="modal" aria-labelledby="new-conversation" @keydown.esc="!busy&&(show=false)"><form @submit.prevent="create"><div class="card-heading"><h2 id="new-conversation">Nueva conversación</h2><button type="button" class="icon-button" aria-label="Cerrar" :disabled="busy" @click="show=false"><X :size="20"/></button></div><Notice v-if="error" error>{{error}}</Notice><label>Cliente<select v-model="customer" required><option value="" disabled>Seleccionar cliente</option><option v-for="c in w.customers" :key="c.id" :value="c.id">{{c.name||c.external_id}}</option></select></label><label>Canal<select v-model="channel"><option value="whatsapp">WhatsApp</option><option value="instagram">Instagram</option><option value="messenger">Messenger</option><option value="web">Web</option></select></label><Notice>Crear el registro no conecta ni activa el canal seleccionado.</Notice><button class="button primary full" :disabled="busy||!customer">{{busy?'Creando…':'Crear conversación'}}</button><RouterLink v-if="!w.customers.length" to="/customers" class="text-link">Primero registra un cliente</RouterLink></form></dialog></template>
